def stage_channel_plan(record):
    channel = str(record.get('channel', ''))
    allowed = sorted({str(item) for item in record.get('allowed_channels', [])})
    prefix = str(record.get('compatibility_prefix', ''))
    return {'channel': channel, 'allowed': allowed, 'prefix': prefix}

def finalize_channel_plan(staged):
    channel = staged.get('channel', '')
    prefix = staged.get('prefix', '')
    matched = channel in staged.get('allowed', []) or (bool(prefix) and channel.startswith(prefix))
    return {'decision': 'allowed' if matched else 'blocked', 'channel': channel}
